const config = $('Watch Configuration').first().json;
const rawBody = $json.body ?? $json.data ?? $json;
const body = typeof rawBody === 'string' ? rawBody : JSON.stringify(rawBody);
const statusCode = Number($json.statusCode ?? 200);

const UNKNOWN = 'UNKNOWN';
const BLOCKED = 'BLOCKED';
const ACTIONABLE = new Set(['IN_STOCK', 'PREORDER']);
const PRIORITY = { PREORDER: 50, IN_STOCK: 40, BACKORDER: 30, OUT_OF_STOCK: 20, UNKNOWN: 10 };

function normalize(raw) {
  if (!raw) return UNKNOWN;
  const text = String(raw)
    .trim()
    .toLowerCase()
    .split('/')
    .pop()
    .replace(/[-_\s]/g, '');

  if (text.includes('preorder') || text.includes('presale')) return 'PREORDER';
  if (text.includes('backorder')) return 'BACKORDER';
  if (text.includes('outofstock') || text.includes('soldout') || text.includes('unavailable') || text.includes('discontinued')) return 'OUT_OF_STOCK';
  if (text.includes('limitedavailability') || text.includes('madetoorder') || text.includes('instock') || text.includes('instoreonly') || text.includes('onlineonly')) return 'IN_STOCK';
  return UNKNOWN;
}

function walk(value, out = []) {
  if (Array.isArray(value)) {
    for (const child of value) walk(child, out);
  } else if (value && typeof value === 'object') {
    out.push(value);
    for (const child of Object.values(value)) {
      if (child && typeof child === 'object') walk(child, out);
    }
  }
  return out;
}

function typeSet(node) {
  const raw = node?.['@type'];
  if (Array.isArray(raw)) return new Set(raw.map(v => String(v).toLowerCase()));
  if (raw) return new Set([String(raw).toLowerCase()]);
  return new Set();
}

function matchesProduct(node, needle) {
  if (!needle) return true;
  const fields = ['name', 'sku', 'mpn', 'productID', 'gtin', 'gtin8', 'gtin12', 'gtin13', 'gtin14'];
  const haystack = fields.map(field => String(node?.[field] ?? '')).join(' ').toLowerCase();
  return haystack.includes(String(needle).toLowerCase());
}

function availabilityValues(node) {
  const values = [];
  const direct = node?.availability;
  if (typeof direct === 'string') values.push(direct);
  if (Array.isArray(direct)) values.push(...direct.filter(v => typeof v === 'string'));

  const offers = node?.offers;
  if (Array.isArray(offers)) {
    for (const offer of offers) values.push(...availabilityValues(offer));
  } else if (offers && typeof offers === 'object') {
    values.push(...availabilityValues(offers));
  }
  return values;
}

function bestStatus(values) {
  const statuses = values.map(normalize).filter(v => v !== UNKNOWN);
  if (!statuses.length) return UNKNOWN;
  return statuses.sort((a, b) => (PRIORITY[b] || 0) - (PRIORITY[a] || 0))[0];
}

function parseJsonLd(html, needle) {
  const scriptPattern = /<script\b[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi;
  const matchingProducts = [];
  const fallbackNodes = [];

  for (const match of html.matchAll(scriptPattern)) {
    let parsed;
    try {
      parsed = JSON.parse(match[1]);
    } catch {
      continue;
    }

    for (const candidate of walk(parsed)) {
      if (availabilityValues(candidate).length) fallbackNodes.push(candidate);
      if (typeSet(candidate).has('product') && matchesProduct(candidate, needle)) {
        matchingProducts.push(candidate);
      }
    }
  }

  const candidates = matchingProducts.length
    ? matchingProducts
    : (needle ? [] : fallbackNodes);

  return bestStatus(candidates.flatMap(availabilityValues));
}

let current = UNKNOWN;

if ($json.error || $json.errorMessage) {
  current = BLOCKED;
} else if (statusCode === 401 || statusCode === 403 || statusCode === 429 || statusCode >= 500) {
  current = BLOCKED;
} else {
  current = parseJsonLd(body, config.match || '');

  if (current === UNKNOWN && !config.match) {
    const looseValues = [...body.matchAll(/"availability"\s*:\s*(?:"([^"]+)"|\[\s*"([^"]+)")/gi)]
      .map(m => m[1] || m[2])
      .filter(Boolean);
    current = bestStatus(looseValues);
  }
}

const state = $getWorkflowStaticData('global');
state.statuses ??= {};
const key = config.label || config.url;
const previous = state.statuses[key] ?? null;

let baseline = false;
let changed = false;
let shouldAlert = false;

if (current !== UNKNOWN && current !== BLOCKED) {
  if (previous === null) {
    state.statuses[key] = current;
    baseline = true;
  } else if (previous !== current) {
    changed = true;
    shouldAlert = ACTIONABLE.has(current);
    state.statuses[key] = current;
  }
}

const title = shouldAlert
  ? `${current === 'PREORDER' ? 'PREORDER' : 'IN STOCK'}: ${config.productName}`
  : `Restock Watch: ${config.productName}`;

const message = shouldAlert
  ? `${config.productName} changed at ${config.label}: ${previous} -> ${current}\n${config.url}`
  : `${config.productName}: ${current}${baseline ? ' (baseline)' : changed ? ` (was ${previous})` : ''}`;

return [{
  json: {
    ...config,
    previous,
    current,
    baseline,
    changed,
    shouldAlert,
    title,
    message,
    checkedAt: new Date().toISOString()
  }
}];
